          ...(exactArmorFaceCoverage ? [] : [`ARMOR_FACE_COVERAGE:${finalBlockFaceArmorInstalled}/${armorableFaces.length}:duplicate=${duplicateArmorFaceKeys.length}:bottom=${bottomArmorCount}:nonflat=${nonFlatArmorCount}`]),
