  ui.lobbyModalTitle.textContent = info[0];
  ui.lobbyModalCopy.textContent = info[1];
  ui.lobbyModalIcon.classList.remove(...LOBBY_ICON_CLASSES);
  ui.lobbyModalIcon.classList.add(info[2]);
