  if (battle) {
    ui.lobbyBattleMap.value = selectedMapId;
    ui.lobbyEnterBattle.textContent = selectedMapId === 'desert01' ? 'RED CANYON 10v10 출전' : 'INDUSTRIAL ZONE 출전';
  }
