  const delta = { forward: [0,0,1], back: [0,0,-1], left: [-1,0,0], right: [1,0,0], up: [0,1,0], down: [0,-1,0] }[button.dataset.mobileNudge];
  candidateBlock.gridPosition = candidateBlock.gridPosition.map((value, index) => value + delta[index]);
